package com.lughzdan.engine
import org.junit.Assert.*
import org.junit.Test
import java.io.File
class GamesTest {
 private fun p(type:String,b:ChoicePayload)=PuzzleDefinition(1,"p",1,"g",type,"words",1,1,"arabic_basic_v1","t","draft",true,listOf("s"),"explanation",listOf(Hint("h","step","hint",10)),b)
 private val order=ChoicePayload(items=listOf(Option("a","A"),Option("b","B")),correctOrder=listOf("b","a"))
 @Test fun legacyPayloadAndStateRemainReadable(){val b=SessionCodec.json.decodeFromString<ChoicePayload>("""{"prompt":"q","options":[],"correctId":"a"}""");assertEquals("a",b.correctId);val s=GameSession("s","p",2,packVersion=4,packId="pack",selectedId="a");assertEquals(s,SessionCodec.decode(SessionCodec.encode(s)))}
 @Test fun noChangeReorderIsAcknowledgedBeforeReplay(){val p=p("order",order);val e=OrderPlugin();var s=e.createSession(p,"s");val a=PlayerAction.Reorder("same",listOf("a","b"));s=e.evaluate(p,s,a);s=e.evaluate(p,s,PlayerAction.Reorder("changed",listOf("b","a")));assertEquals(s,e.evaluate(p,s,a))}
 @Test fun orderRejectsDuplicateItemsAndChargesHintOnce(){val p=p("order",order);val e=OrderPlugin();var s=e.createSession(p,"s");assertEquals(s,e.evaluate(p,s,PlayerAction.Reorder("bad",listOf("a","a"))));repeat(2){s=e.evaluate(p,s,PlayerAction.UseHint("h$it","h"))};s=e.evaluate(p,s,PlayerAction.Reorder("r",listOf("b","a")));s=e.evaluate(p,s,PlayerAction.Submit("win"));assertEquals(90,s.score);assertTrue(e.validateSession(p,s).valid);assertEquals(s,e.evaluate(p,s,PlayerAction.UseHint("x","h")))}
 @Test fun duplicateLettersAreDistinctTiles(){val p=p("anagram",ChoicePayload(tiles=listOf("ب","ب"),acceptedAnswers=listOf("بب")));val e=AnagramPlugin();var s=e.createSession(p,"s");s=e.evaluate(p,s,PlayerAction.AddTile("1",0));assertEquals(s,e.evaluate(p,s,PlayerAction.AddTile("2",0)));s=e.evaluate(p,s,PlayerAction.AddTile("3",1));s=e.evaluate(p,s,PlayerAction.Undo("4"));assertEquals(listOf(0),s.selectedTileIndices);s=e.evaluate(p,s,PlayerAction.AddTile("5",1));assertEquals(SessionStatus.WON,e.evaluate(p,s,PlayerAction.Submit("win")).status)}
 @Test fun fixedSlotConsumesInventory(){val p=p("anagram",ChoicePayload(tiles=listOf("ت","ا","ب"),fixedSlots=listOf(FixedSlot(0,"ب")),acceptedAnswers=listOf("بات")));val e=AnagramPlugin();var s=e.createSession(p,"s");assertEquals(s,e.evaluate(p,s,PlayerAction.AddTile("reserved",2)));s=e.evaluate(p,s,PlayerAction.AddTile("1",1));s=e.evaluate(p,s,PlayerAction.AddTile("2",0));assertEquals(SessionStatus.WON,e.evaluate(p,s,PlayerAction.Submit("win")).status);assertFalse(e.validatePuzzle(p.copy(payload=p.payload.copy(tiles=listOf("ت","ا")))).valid)}
 private val cross=ChoicePayload(rows=3,cols=3,entries=listOf(CrosswordEntry("a",0,1,"across",listOf("ب","ت"),"q","s"),CrosswordEntry("b",0,1,"down",listOf("ب","ا"),"q","s")))
 @Test fun crosswordDirectionAndConflictValidation(){val p=p("crossword",cross);val e=CrosswordPlugin();assertTrue(e.validatePuzzle(p).valid);var s=e.createSession(p,"s");assertEquals(s,e.evaluate(p,s,PlayerAction.InputCell("bad",2,2,"ب")));assertEquals(s,e.evaluate(p,s,PlayerAction.InputCell("bad",0,1,"بت")));for((i,c) in listOf(Triple(0,1,"ب"),Triple(0,0,"ت"),Triple(1,1,"ا")).withIndex()) s=e.evaluate(p,s,PlayerAction.InputCell("$i",c.first,c.second,c.third));assertEquals(SessionStatus.WON,e.evaluate(p,s,PlayerAction.Submit("win")).status);assertFalse(e.validatePuzzle(p.copy(payload=cross.copy(entries=cross.entries.map {if(it.id=="b") it.copy(tokens=listOf("س","ا")) else it}))).valid)}
 private val search=ChoicePayload(grid=listOf(listOf("ب","ا","ت"),listOf("س","س","س"),listOf("س","س","س")),words=listOf(SearchWord("w","بات",listOf(Cell(0,0),Cell(0,1),Cell(0,2)))))
 @Test fun searchDraftRequiresSubmitAndReverseWorks(){val p=p("wordsearch",search);val e=WordsearchPlugin();var s=e.createSession(p,"s");s=e.evaluate(p,s,PlayerAction.SelectPath("path",search.words[0].path.reversed()));assertEquals(SessionStatus.ACTIVE,s.status);s=e.evaluate(p,s,PlayerAction.Submit("win"));assertEquals(SessionStatus.WON,s.status);assertTrue(e.validateSession(p,s).valid)}
 @Test fun searchWrongVerificationCostsAttempt(){val p=p("wordsearch",search);val e=WordsearchPlugin();var s=e.createSession(p,"s");s=e.evaluate(p,s,PlayerAction.SelectPath("path",listOf(Cell(1,0),Cell(1,1))));assertEquals(0,s.wrongSubmissions);s=e.evaluate(p,s,PlayerAction.Submit("bad"));assertEquals(1,s.wrongSubmissions);assertEquals(s,e.evaluate(p,s,PlayerAction.Submit("bad")))}
 @Test fun unsolvablePayloadsRejectSafely(){
  val e=WordsearchPlugin();assertFalse(e.validatePuzzle(p("wordsearch",search.copy(words=search.words+search.words[0].copy(id="duplicate")))).valid)
  assertFalse(e.validatePuzzle(p("wordsearch",search.copy(grid=listOf(listOf("ب","ا","ت"),emptyList(),listOf("س","س","س")),words=listOf(SearchWord("bad","بات",listOf(Cell(1,0),Cell(1,1),Cell(1,2))))))).valid)
  assertFalse(AnagramPlugin().validatePuzzle(p("anagram",ChoicePayload(tiles=listOf("ب","ت"),fixedSlots=listOf(FixedSlot(0,"ب"),FixedSlot(1,"ت")),acceptedAnswers=listOf("بت")))).valid)
 }
 @Test fun accidentalSearchOccurrenceRejected(){val b=search.copy(grid=listOf(listOf("ب","ا","ت"),listOf("ب","ا","ت"),listOf("س","س","س")));assertFalse(WordsearchPlugin().validatePuzzle(p("wordsearch",b)).valid)}
 private val pairs=ChoicePayload(left=listOf(Option("a","A"),Option("b","B")),right=listOf(Option("x","X"),Option("y","Y")),pairs=listOf(MatchPair("a","x"),MatchPair("b","y")))
 @Test fun matchingEditsAreFreeButWrongFullVerificationLoses(){val p=p("matching",pairs);val e=MatchingPlugin();var s=e.createSession(p,"s");s=e.evaluate(p,s,PlayerAction.Match("1","a","y"));assertEquals(0,s.wrongSubmissions);assertEquals(s,e.evaluate(p,s,PlayerAction.Submit("partial")));s=e.evaluate(p,s,PlayerAction.Match("2","b","x"));repeat(3){s=e.evaluate(p,s,PlayerAction.Submit("bad$it"))};assertEquals(SessionStatus.LOST,s.status)}
 @Test fun semanticChoiceUsesMatchingWithExplicitSubmit(){val p=p("matching",ChoicePayload("اختر",listOf(Option("a","علم"),Option("b","قلم"),Option("c","دار"),Option("d","باب")),"b",variant="intruder"));val e=MatchingPlugin();assertTrue(e.validatePuzzle(p).valid);var s=e.createSession(p,"s");s=e.evaluate(p,s,PlayerAction.Select("pick","a"));assertEquals(0,s.wrongSubmissions);s=e.evaluate(p,s,PlayerAction.Submit("wrong"));assertEquals(1,s.wrongSubmissions);assertNull(s.selectedId);s=e.evaluate(p,s,PlayerAction.Select("pick2","b"));s=e.evaluate(p,s,PlayerAction.Submit("right"));assertEquals(SessionStatus.WON,s.status);assertTrue(e.validateSession(p,s).valid)}
 @Test fun matchingReplaceAndWin(){val p=p("matching",pairs);val e=MatchingPlugin();var s=e.createSession(p,"s");s=e.evaluate(p,s,PlayerAction.Match("1","a","y"));s=e.evaluate(p,s,PlayerAction.Match("2","a","x"));assertEquals(1,s.matchedPairs.size);s=e.evaluate(p,s,PlayerAction.Match("3","b","y"));assertEquals(SessionStatus.WON,e.evaluate(p,s,PlayerAction.Submit("win")).status)}
 @Test fun multipleBuilderCollectsDistinctTargets(){val p=p("anagram",ChoicePayload(tiles=listOf("ك","ت","ب"),acceptedAnswers=listOf("كتب","بت"),variant="multi_word"));val e=AnagramPlugin();var s=e.createSession(p,"s");for(i in 0..2) s=e.evaluate(p,s,PlayerAction.AddTile("a$i",i));s=e.evaluate(p,s,PlayerAction.Submit("first"));assertEquals(SessionStatus.ACTIVE,s.status);assertEquals(0,s.score);for(i in listOf(2,1)) s=e.evaluate(p,s,PlayerAction.AddTile("b$i",i));s=e.evaluate(p,s,PlayerAction.Submit("second"));assertEquals(SessionStatus.WON,s.status);assertTrue(e.validateSession(p,s).valid)}
 @Test fun normalizedMatchingDuplicatesReject(){assertFalse(MatchingPlugin().validatePuzzle(p("matching",pairs.copy(left=listOf(Option("a","عِلْم"),Option("b","علم"))))).valid)}
 @Test fun forgedTerminalAndForeignProgressRejected(){val p=p("order",order);val e=OrderPlugin();val s=e.createSession(p,"s");assertFalse(e.validateSession(p,s.copy(status=SessionStatus.WON,score=100)).valid);assertFalse(e.validateSession(p,s.copy(cells=mapOf("0,0" to "ب"))).valid)}
 @Test fun arabicTokenPolicy(){assertTrue(validToken("عِ"));assertFalse(validToken("\uD83D\uDE00"));assertFalse(validToken("\uFEFB"));assertFalse(validToken("ِ"));assertFalse(validToken("علم"));assertFalse(validToken("\u202E"));assertNotEquals(normalized(p("order",order),"أمل"),normalized(p("order",order),"امل"))}
 @Test fun revealedHintsPersistAcrossBoardMovesAndRestore(){val p=p("crossword",cross);val e=CrosswordPlugin();var s=e.createSession(p,"s");s=e.evaluate(p,s,PlayerAction.UseHint("hint","h"));val text=s.revealedHints["h"];assertTrue(text?.contains("ب")==true);s=e.evaluate(p,s,PlayerAction.InputCell("input",0,1,"ب"));s=e.evaluate(p,s,PlayerAction.UseHint("again","h"));assertEquals(text,s.revealedHints["h"]);val restored=SessionCodec.restore(SessionCodec.encode(s));assertEquals(text,restored.revealedHints["h"]);assertTrue(e.validateSession(p,restored).valid);assertEquals(setOf("h"),s.usedHintIds)}
 @Test fun hintsDoNotChargeUntilAppliedAndDifficultyUsesHistory(){val p=p("order",order);val e=OrderPlugin();val s=e.createSession(p,"s");assertEquals("h",HintProvider.next(p,s)?.hint?.id);assertTrue(s.usedHintIds.isEmpty());assertNull(HintProvider.next(p,e.evaluate(p,s,PlayerAction.UseHint("use","h"))));assertEquals(2,DifficultyController.nextDifficulty(2,listOf(s.copy(status=SessionStatus.WON))));assertEquals(3,DifficultyController.nextDifficulty(2,List(3){s.copy(status=SessionStatus.WON)}));assertEquals(1,DifficultyController.nextDifficulty(2,List(3){s.copy(status=SessionStatus.LOST,wrongSubmissions=3)}));assertEquals(2,DifficultyController.metrics(p).size)}
 @Test fun generatorLimitsAndVariantWhitelist(){val w=GeneratorWord("a",listOf("ب","ا"),"q","s");assertTrue(CrosswordGenerator.generate(List(61){w},5,5,0) is GenerationResult.Failure);assertTrue(WordSearchGenerator.generate(listOf(w),5,5,0,maxAttempts=50001) is GenerationResult.Failure);assertFalse(OrderPlugin().validatePuzzle(p("order",order.copy(variant="unknown"))).valid);assertFalse(validToken("ب"+"ِ".repeat(20)))}
 @Test fun generatorsAreDeterministicBoundedAndValid(){val words=listOf(GeneratorWord("a",listOf("ب","ا","ت"),"q","s"),GeneratorWord("b",listOf("ا","س"),"q","s"));val samples=mutableListOf<Long>();var successes=0;var crosswordSuccesses=0;var searchSuccesses=0
  for(seed in 0..40){val start=System.nanoTime();val x=CrosswordGenerator.generate(words,5,5,seed,10000);val y=WordSearchGenerator.generate(words,5,5,seed,maxAttempts=10000);samples.add(System.nanoTime()-start);assertEquals(x,CrosswordGenerator.generate(words,5,5,seed,10000));assertEquals(y,WordSearchGenerator.generate(words,5,5,seed,maxAttempts=10000));if(x is GenerationResult.Success){successes++;crosswordSuccesses++;assertTrue(CrosswordPlugin().validatePuzzle(p("crossword",x.payload)).valid)};if(y is GenerationResult.Success){successes++;searchSuccesses++;assertTrue(WordsearchPlugin().validatePuzzle(p("wordsearch",y.payload)).valid)}}
  assertTrue("crossword seed corpus produced no valid boards",crosswordSuccesses>0);assertTrue("wordsearch seed corpus produced no valid boards",searchSuccesses>0);assertTrue(CrosswordGenerator.generate(words,5,5,0,1) is GenerationResult.Failure);assertTrue(WordSearchGenerator.generate(words,2,2,0) is GenerationResult.Failure);samples.sort();println("generator_pair_ms p50=${samples[20]/1e6} p95=${samples[38]/1e6} runs=41 successes=$successes java=${System.getProperty("java.version")} os=${System.getProperty("os.name")}")
 }
 @Test fun wordsearchRetriesAccidentalFillerWithinSharedBudget(){
  val words=listOf(GeneratorWord("a",listOf("ب","ا","ت"),"q","s"),GeneratorWord("b",listOf("ا","س"),"q","s"))
  val result=WordSearchGenerator.generate(words,5,5,0,maxAttempts=10000)
  assertTrue("seed 0 must recover from accidental filler occurrences: $result",result is GenerationResult.Success)
  result as GenerationResult.Success
  assertTrue(WordsearchPlugin().validatePuzzle(p("wordsearch",result.payload)).valid)
  assertEquals(result,WordSearchGenerator.generate(words,5,5,0,maxAttempts=10000))
  assertEquals(GenerationResult.Failure("attempt_budget_exhausted"),WordSearchGenerator.generate(words,5,5,0,maxAttempts=1))
  val impossible=listOf(GeneratorWord("a",listOf("ا","ا"),"q","s"))
  assertEquals(GenerationResult.Failure("attempt_budget_exhausted"),WordSearchGenerator.generate(impossible,3,3,0,filler=listOf("ا"),maxAttempts=100))
 }
 @Test fun allBundledFixturesValidate(){var dir=File(System.getProperty("user.dir"));while(!File(dir,"contracts").isDirectory&&dir.parentFile!=null) dir=dir.parentFile;val files=File(dir,"apps/android/app/src/debug/assets").walkTopDown().filter {it.extension=="jsonl"}.toList();assertTrue(files.isNotEmpty());val registry=GameRegistry();var count=0;files.forEach {file->file.readLines().filter {it.isNotBlank()}.forEach {line->val p=SessionCodec.json.decodeFromString<PuzzleDefinition>(line);val result=registry.plugin(p.type).validatePuzzle(p);assertTrue("${p.puzzleId}: ${result.errors}",result.valid);count++}};assertTrue(count>=22)}
}
